function waitInvoiceReady(emitter) {
  return new Promise((resolve, reject) => {
    const onReady = data => {
      cleanup();
      resolve(data);
    };
    const onError = err => {
      cleanup();
      reject(err);
    };
    const cleanup = () => {
      emitter.off('invoice_ready', onReady);
      emitter.off('error', onError);
    };
    emitter.once('invoice_ready', onReady);
    emitter.once('error', onError);
  });
}

