  return new Promise((resolve, reject) => {
    const onReady = data => {
      cleanup();
      resolve(data);
    };
    const onError = err => {
      cleanup();
      reject(err);
    };
    const cleanup = () => {
      emitter.off('task_ready', onReady);
      emitter.off('error', onError);
