  const firstRes = await fetch(`/api/users?page=1&limit=100`);
  const firstPage = await firstRes.json();
  const totalPages = firstPage.totalPages;
  const pageNums = Array.from({
    length: totalPages - 1
  }, (_, i) => i + 2);
  const results = [...firstPage.items];
  for (let i = 0; i < pageNums.length; i += concurrency) {
    const batch = pageNums.slice(i, i + concurrency);
    const pages = await Promise.all(batch.map(p => fetch(`/api/users?page=${p}&limit=100`).then(r => r.json())));
    pages.forEach(p => results.push(...p.items));
  }
  return results;
}

