function waitPaymentReady(emitter) {
  return new Promise((resolve, reject) => {
    const onReady = data => {
      cleanup();
      resolve(data);
    };
    const onError = err => {
      cleanup();
      reject(err);
    };
    const cleanup = () => {
      emitter.off('payment_ready', onReady);
      emitter.off('error', onError);
    };
    emitter.once('payment_ready', onReady);
    emitter.once('error', onError);
  });
}

