async function getCategory(id) {
  if (cache.has(id)) return cache.get(id);
  if (inflight.has(id)) return inflight.get(id);
  const promise = fetch(`/api/categories/${id}`).then(r => r.json()).then(data => {
    cache.set(id, data);
    inflight.delete(id);
    return data;
  });
  inflight.set(id, promise);
  return promise;
}

