async function fetchTicketWithRetry(id, retries = 2) {
  for (let i = 0; i <= retries; i++) {
    try {
      const res = await fetch(`/api/tickets/${id}`);
      if (!res.ok) throw new Error(res.status);
      return await res.json();
    } catch (err) {
      if (i === retries) throw err;
      await new Promise(r => setTimeout(r, 300 * (i + 1)));
    }
  }
}
async function loadAllTickets(ids) {
  return Promise.allSettled(ids.map(id => fetchTicketWithRetry(id))).then(results => results.filter(r => r.status === 'fulfilled').map(r => r.value));
}

