    method: 'POST',
    body: JSON.stringify(filters)
  });
  const reader = res.body.getReader();
  const decoder = new TextDecoder();
  let buffer = '';
  while (true) {
    const {
      done,
      value
    } = await reader.read();
    if (done) break;
