function waitTransactionReady(emitter) {
  return new Promise((resolve, reject) => {
    const onReady = data => {
      cleanup();
      resolve(data);
    };
    const onError = err => {
      cleanup();
      reject(err);
    };
    const cleanup = () => {
      emitter.off('transaction_ready', onReady);
      emitter.off('error', onError);
    };
